static gboolean __ConfigmgrManagerresponseHandler(gpointer data)
{
	RequestInfo *request = static_cast<RequestInfo*>(data);
	g_thread_join(request->thread);

	// invoke the callback function
	bool retval = request->processor(*(request->p_chunk), *(request->code), request->errormsg, request->userData, request->handler);

	delete request;
	return FALSE;
}

static gpointer __ConfigmgrManagerthreadFunc(gpointer data)
{
	RequestInfo *request = static_cast<RequestInfo*>(data);

	// handle the request
	NetClient::easycurl(request->host, request->path, request->method, request->queryParams,
	request->mBody, request->headerList, request->p_chunk, request->code, request->errormsg);

	request->thread = g_thread_self();
	g_idle_add(__ConfigmgrManagerresponseHandler, static_cast<gpointer>(request));

	return NULL;
}


static bool adaptiveFormAndInteractiveCommunicationWebChannelConfigurationProcessor(MemoryStruct_s p_chunk, long code, char* errormsg, void* userData,
	void(* voidHandler)())
{
	void(* handler)(AdaptiveFormAndInteractiveCommunicationWebChannelConfigurationInfo, Error, void* )
	= reinterpret_cast<void(*)(AdaptiveFormAndInteractiveCommunicationWebChannelConfigurationInfo, Error, void* )> (voidHandler);
	
	JsonNode* pJson;
	char * data = p_chunk.memory;

	
	AdaptiveFormAndInteractiveCommunicationWebChannelConfigurationInfo out;

	if (code >= 200 && code < 300) {
		Error error(code, string("No Error"));




		if (isprimitive("AdaptiveFormAndInteractiveCommunicationWebChannelConfigurationInfo")) {
			pJson = json_from_string(data, NULL);
			jsonToValue(&out, pJson, "AdaptiveFormAndInteractiveCommunicationWebChannelConfigurationInfo", "AdaptiveFormAndInteractiveCommunicationWebChannelConfigurationInfo");
			json_node_free(pJson);

			if ("AdaptiveFormAndInteractiveCommunicationWebChannelConfigurationInfo" == "std::string") {
				string* val = (std::string*)(&out);
				if (val->empty() && p_chunk.size>4) {
					*val = string(p_chunk.memory, p_chunk.size);
				}
			}
		} else {
			
			out.fromJson(data);
			char *jsonStr =  out.toJson();
			printf("\n%s\n", jsonStr);
			g_free(static_cast<gpointer>(jsonStr));
			
		}
		handler(out, error, userData);
		return true;
		//TODO: handle case where json parsing has an error

	} else {
		Error error;
		if (errormsg != NULL) {
			error = Error(code, string(errormsg));
		} else if (p_chunk.memory != NULL) {
			error = Error(code, string(p_chunk.memory));
		} else {
			error = Error(code, string("Unknown Error"));
		}
		 handler(out, error, userData);
		return false;
			}
}

static bool adaptiveFormAndInteractiveCommunicationWebChannelConfigurationHelper(char * accessToken,
	bool post, bool apply, bool r_delete, std::string action, std::string Dollarlocation, std::list<std::string> propertylist, bool showPlaceholder, int maximumCacheEntries, std::string afPeriodscriptingPeriodcompatversion, bool makeFileNameUnique, bool generatingCompliantData, 
	void(* handler)(AdaptiveFormAndInteractiveCommunicationWebChannelConfigurationInfo, Error, void* )
	, void* userData, bool isAsync)
{

	//TODO: maybe delete headerList after its used to free up space?
	struct curl_slist *headerList = NULL;

	
	string accessHeader = "Authorization: Bearer ";
	accessHeader.append(accessToken);
	headerList = curl_slist_append(headerList, accessHeader.c_str());
	headerList = curl_slist_append(headerList, "Content-Type: application/json");

	map <string, string> queryParams;
	string itemAtq;
	

	itemAtq = stringify(&post, "bool");
	queryParams.insert(pair<string, string>("post", itemAtq));
	if( itemAtq.empty()==true){
		queryParams.erase("post");
	}


	itemAtq = stringify(&apply, "bool");
	queryParams.insert(pair<string, string>("apply", itemAtq));
	if( itemAtq.empty()==true){
		queryParams.erase("apply");
	}


	itemAtq = stringify(&r_delete, "bool");
	queryParams.insert(pair<string, string>("delete", itemAtq));
	if( itemAtq.empty()==true){
		queryParams.erase("delete");
	}


	itemAtq = stringify(&action, "std::string");
	queryParams.insert(pair<string, string>("action", itemAtq));
	if( itemAtq.empty()==true){
		queryParams.erase("action");
	}


	itemAtq = stringify(&Dollarlocation, "std::string");
	queryParams.insert(pair<string, string>("$location", itemAtq));
	if( itemAtq.empty()==true){
		queryParams.erase("$location");
	}

	for (std::list
	<std::string>::iterator queryIter = propertylist.begin(); queryIter != propertylist.end(); ++queryIter) {
		string itemAt = stringify(&(*queryIter), "std::string");
		if( itemAt.empty()){
			continue;
		}
		queryParams.insert(pair<string, string>("propertylist", itemAt));
	}
	

	itemAtq = stringify(&showPlaceholder, "bool");
	queryParams.insert(pair<string, string>("showPlaceholder", itemAtq));
	if( itemAtq.empty()==true){
		queryParams.erase("showPlaceholder");
	}


	itemAtq = stringify(&maximumCacheEntries, "int");
	queryParams.insert(pair<string, string>("maximumCacheEntries", itemAtq));
	if( itemAtq.empty()==true){
		queryParams.erase("maximumCacheEntries");
	}


	itemAtq = stringify(&afPeriodscriptingPeriodcompatversion, "std::string");
	queryParams.insert(pair<string, string>("af.scripting.compatversion", itemAtq));
	if( itemAtq.empty()==true){
		queryParams.erase("af.scripting.compatversion");
	}


	itemAtq = stringify(&makeFileNameUnique, "bool");
	queryParams.insert(pair<string, string>("makeFileNameUnique", itemAtq));
	if( itemAtq.empty()==true){
		queryParams.erase("makeFileNameUnique");
	}


	itemAtq = stringify(&generatingCompliantData, "bool");
	queryParams.insert(pair<string, string>("generatingCompliantData", itemAtq));
	if( itemAtq.empty()==true){
		queryParams.erase("generatingCompliantData");
	}

	string mBody = "";
	JsonNode* node;
	JsonArray* json_array;

	string url("/system/console/configMgr/Adaptive Form and Interactive Communication Web Channel Configuration");
	int pos;


	//TODO: free memory of errormsg, memorystruct
	MemoryStruct_s* p_chunk = new MemoryStruct_s();
	long code;
	char* errormsg = NULL;
	string myhttpmethod("POST");

	if(strcmp("PUT", "POST") == 0){
		if(strcmp("", mBody.c_str()) == 0){
			mBody.append("{}");
		}
	}

	if(!isAsync){
		NetClient::easycurl(ConfigmgrManager::getBasePath(), url, myhttpmethod, queryParams,
			mBody, headerList, p_chunk, &code, errormsg);
		bool retval = adaptiveFormAndInteractiveCommunicationWebChannelConfigurationProcessor(*p_chunk, code, errormsg, userData,reinterpret_cast<void(*)()>(handler));

		curl_slist_free_all(headerList);
		if (p_chunk) {
			if(p_chunk->memory) {
				free(p_chunk->memory);
			}
			delete (p_chunk);
		}
		if (errormsg) {
			free(errormsg);
		}
		return retval;
	} else{
		GThread *thread = NULL;
		RequestInfo *requestInfo = NULL;

		requestInfo = new(nothrow) RequestInfo (ConfigmgrManager::getBasePath(), url, myhttpmethod, queryParams,
			mBody, headerList, p_chunk, &code, errormsg, userData, reinterpret_cast<void(*)()>(handler), adaptiveFormAndInteractiveCommunicationWebChannelConfigurationProcessor);;
		if(requestInfo == NULL)
			return false;

		thread = g_thread_new(NULL, __ConfigmgrManagerthreadFunc, static_cast<gpointer>(requestInfo));
		return true;
	}
}




