static bool comAdobeGraniteAuthImsProcessor(MemoryStruct_s p_chunk, long code, char* errormsg, void* userData,
	void(* voidHandler)())
{
	void(* handler)(ComAdobeGraniteAuthImsInfo, Error, void* )
	= reinterpret_cast<void(*)(ComAdobeGraniteAuthImsInfo, Error, void* )> (voidHandler);
	
	JsonNode* pJson;
	char * data = p_chunk.memory;

	
	ComAdobeGraniteAuthImsInfo out;

	if (code >= 200 && code < 300) {
		Error error(code, string("No Error"));




		if (isprimitive("ComAdobeGraniteAuthImsInfo")) {
			pJson = json_from_string(data, NULL);
			jsonToValue(&out, pJson, "ComAdobeGraniteAuthImsInfo", "ComAdobeGraniteAuthImsInfo");
			json_node_free(pJson);

			if ("ComAdobeGraniteAuthImsInfo" == "std::string") {
				string* val = (std::string*)(&out);
				if (val->empty() && p_chunk.size>4) {
					*val = string(p_chunk.memory, p_chunk.size);
				}
			}
		} else {
			
			out.fromJson(data);
			char *jsonStr =  out.toJson();
			printf("\n%s\n", jsonStr);
			g_free(static_cast<gpointer>(jsonStr));
			
		}
		handler(out, error, userData);
		return true;
		//TODO: handle case where json parsing has an error

	} else {
		Error error;
		if (errormsg != NULL) {
			error = Error(code, string(errormsg));
		} else if (p_chunk.memory != NULL) {
			error = Error(code, string(p_chunk.memory));
		} else {
			error = Error(code, string("Unknown Error"));
		}
		 handler(out, error, userData);
		return false;
			}
}

